import faulthandler
from pathlib import Path
import tempfile
import unittest

import config
from views import check_demo


def main():
    """Run the source-specific acceptance scenario without accessing production data."""
    with tempfile.TemporaryDirectory(prefix='weekwise-uniclubs-acceptance-') as directory:
        check_demo.isolate_paths(Path(directory) / 'data')
        config.UNICLUBS_FEED_ENABLED = True
        # Defaults bind when modules load, so import only after all data paths are isolated.
        from views import uniclubs_scenario
        suite = unittest.defaultTestLoader.loadTestsFromTestCase(
            uniclubs_scenario.UniClubsScenario)
        faulthandler.dump_traceback_later(150)
        try:
            result = unittest.TextTestRunner(verbosity=2).run(suite)
        finally:
            faulthandler.cancel_dump_traceback_later()
        return 0 if result.wasSuccessful() else 1


if __name__ == '__main__':
    raise SystemExit(main())
